package curated

import (
	"fmt"
	"regexp"
	"testing"
)

// Code generated by regengo
// Tests and benchmarks for pattern: cat|dog|fish

var dFAAlternationRegexp = regexp.MustCompile("cat|dog|fish")

var dFAAlternationTestInputs = []string{"catfish", "dogcat", "fish", "bird"}

func TestDFAAlternationMatchString(t *testing.T) {
	for _, input := range dFAAlternationTestInputs {
		expected := dFAAlternationRegexp.MatchString(input)
		got := DFAAlternation{}.MatchString(input)
		if got != expected {
			t.Errorf("MatchString(%q) = %v, want %v", input, got, expected)
		}
	}
}

func TestDFAAlternationMatchBytes(t *testing.T) {
	for _, input := range dFAAlternationTestInputs {
		inputBytes := []byte(input)
		expected := dFAAlternationRegexp.Match(inputBytes)
		got := DFAAlternation{}.MatchBytes(inputBytes)
		if got != expected {
			t.Errorf("MatchBytes(%q) = %v, want %v", input, got, expected)
		}
	}
}

func BenchmarkDFAAlternation(b *testing.B) {
	inputs := dFAAlternationTestInputs

	b.Run("Match", func(b *testing.B) {
		for i, input := range inputs {
			input := input
			b.Run(fmt.Sprintf("Input[%d]", i), func(b *testing.B) {
				b.Run("stdlib", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = dFAAlternationRegexp.MatchString(input)
					}
				})
				b.Run("regengo", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = DFAAlternation{}.MatchString(input)
					}
				})
			})
		}
	})

}
